namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];
    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Bruschetta", Category = "Appetizers",
                Ingredients = "Baguette\nTomatoes\nFresh basil\nGarlic\nOlive oil\nBalsamic vinegar\nSalt and pepper",
                Steps = "1. Slice and toast the baguette.\n2. Dice tomatoes and mix with chopped basil, minced garlic, olive oil, and balsamic vinegar.\n3. Season with salt and pepper.\n4. Spoon the tomato mixture onto the toasted bread and serve immediately.",
                Ratings = [4, 5, 5, 4]
            },
            new()
            {
                Id = 2, Title = "Stuffed Mushrooms", Category = "Appetizers",
                Ingredients = "Button mushrooms\nCream cheese\nGarlic\nParmesan\nBreadcrumbs\nParsley\nOlive oil",
                Steps = "1. Remove stems from mushrooms and hollow out caps.\n2. Mix cream cheese, minced garlic, Parmesan, breadcrumbs, and parsley.\n3. Fill each mushroom cap with the mixture.\n4. Drizzle with olive oil and bake at 375°F for 20 minutes.",
                Ratings = [5, 4, 4]
            },
            new()
            {
                Id = 3, Title = "Spaghetti Carbonara", Category = "Main Courses",
                Ingredients = "Spaghetti\nPancetta\nEggs\nParmesan cheese\nBlack pepper\nSalt",
                Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Fry pancetta until crispy.\n3. Whisk eggs with grated Parmesan and black pepper.\n4. Toss hot pasta with pancetta, then quickly stir in the egg mixture off heat.\n5. Serve immediately with extra Parmesan.",
                Ratings = [5, 5, 4, 5, 5]
            },
            new()
            {
                Id = 4, Title = "Chicken Tikka Masala", Category = "Main Courses",
                Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nOnion\nGarlic\nGinger\nRice",
                Steps = "1. Marinate chicken in yogurt, garam masala, turmeric, and cumin for 1 hour.\n2. Grill or pan-fry chicken until cooked through.\n3. Sauté onion, garlic, and ginger, then add tomato sauce and cream.\n4. Add chicken to the sauce and simmer for 15 minutes.\n5. Serve over steamed rice.",
                Ratings = [5, 4, 5, 4]
            },
            new()
            {
                Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract\nPowdered sugar",
                Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until fluffy, then fold in the chocolate mixture.\n3. Add flour and vanilla extract, mix gently.\n4. Pour into greased ramekins and bake at 425°F for 12 minutes.\n5. Invert onto plates and dust with powdered sugar.",
                Ratings = [5, 5, 5, 4, 5]
            },
            new()
            {
                Id = 6, Title = "Tiramisu", Category = "Desserts",
                Ingredients = "Ladyfinger biscuits\nEspresso\nMascarpone\nEggs\nSugar\nCocoa powder\nKahlúa (optional)",
                Steps = "1. Brew espresso and let it cool; optionally add Kahlúa.\n2. Whisk egg yolks with sugar until pale, then fold in mascarpone.\n3. Whip egg whites to stiff peaks and fold into mascarpone mixture.\n4. Dip ladyfingers in espresso and layer in a dish.\n5. Spread mascarpone cream over each layer. Repeat.\n6. Refrigerate for 4 hours and dust with cocoa powder before serving.",
                Ratings = [5, 5, 4]
            },
            new()
            {
                Id = 7, Title = "Caesar Salad", Category = "Salads",
                Ingredients = "Romaine lettuce\nCroutons\nParmesan\nCaesar dressing\nLemon juice\nAnchovy paste\nGarlic",
                Steps = "1. Wash and chop romaine lettuce.\n2. Make dressing: whisk Caesar dressing base with lemon juice, anchovy paste, and minced garlic.\n3. Toss lettuce with dressing and croutons.\n4. Top with shaved Parmesan and freshly ground pepper.",
                Ratings = [4, 4, 3, 4]
            },
            new()
            {
                Id = 8, Title = "Greek Salad", Category = "Salads",
                Ingredients = "Cucumber\nTomatoes\nRed onion\nKalamata olives\nFeta cheese\nOlive oil\nOregano\nLemon juice",
                Steps = "1. Chop cucumber, tomatoes, and red onion into chunks.\n2. Add Kalamata olives and crumbled feta.\n3. Drizzle with olive oil and lemon juice.\n4. Sprinkle with dried oregano and toss gently.",
                Ratings = [4, 5, 4]
            },
            new()
            {
                Id = 9, Title = "Tomato Basil Soup", Category = "Soups",
                Ingredients = "Canned tomatoes\nOnion\nGarlic\nFresh basil\nVegetable broth\nHeavy cream\nOlive oil\nSalt and pepper",
                Steps = "1. Sauté diced onion and garlic in olive oil until soft.\n2. Add canned tomatoes and vegetable broth; bring to a boil.\n3. Simmer for 20 minutes, then blend until smooth.\n4. Stir in heavy cream and chopped basil.\n5. Season with salt and pepper.",
                Ratings = [4, 5, 5, 4, 5]
            },
            new()
            {
                Id = 10, Title = "French Onion Soup", Category = "Soups",
                Ingredients = "Yellow onions\nButter\nBeef broth\nDry white wine\nThyme\nBay leaf\nFrench bread\nGruyère cheese",
                Steps = "1. Slice onions thinly and cook in butter over low heat for 40 minutes until caramelized.\n2. Add wine and cook until reduced.\n3. Add beef broth, thyme, and bay leaf; simmer 20 minutes.\n4. Ladle into oven-safe bowls, top with bread and Gruyère.\n5. Broil until cheese is bubbly and golden.",
                Ratings = [5, 5, 4, 5]
            }
        ];
        _nextId = 11;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _displayRating ? "filled" : "")"
              @onclick="() => SubmitRating(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0"
              role="button"
              title="Rate @star star@(star > 1 ? "s" : "")">
            ★
        </span>
    }
    <span class="rating-info">
        @if (_submitted)
        {
            <span class="rating-thanks">Thanks for rating!</span>
        }
        @if (_recipe is not null && _recipe.Ratings.Count > 0)
        {
            <span class="rating-avg">@_recipe.AverageRating.ToString("F1") avg (@_recipe.Ratings.Count ratings)</span>
        }
    </span>
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    private Recipe? _recipe;
    private int _hoverRating;
    private bool _submitted;

    private int _displayRating => _hoverRating > 0 ? _hoverRating : (_submitted ? _lastRating : 0);
    private int _lastRating;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(RecipeId);
    }

    private void SubmitRating(int rating)
    {
        RecipeService.AddRating(RecipeId, rating);
        _lastRating = rating;
        _submitted = true;
        _recipe = RecipeService.GetById(RecipeId);
    }
}

@page "/category/{CategoryName}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName</h1>

@if (_recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100 recipe-card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            @if (recipe.Ratings.Count > 0)
                            {
                                <span>★ @recipe.AverageRating.ToString("F1") (@recipe.Ratings.Count ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-link mt-3">← Back to categories</a>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@inject RecipeService RecipeService

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeShare</PageTitle>
    <h1>Recipe not found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="/" class="btn btn-link">← Back to home</a>
}
else
{
    <PageTitle>@_recipe.Title — RecipeShare</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>

    <StarRating RecipeId="@_recipe.Id" />

    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Ingredients</h5></div>
                <div class="card-body">
                    <ul class="list-unstyled mb-0">
                        @foreach (var ingredient in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li class="mb-1">• @ingredient.Trim()</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Instructions</h5></div>
                <div class="card-body">
                    @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step.Trim()</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services
@using System.ComponentModel.DataAnnotations
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

<div class="row">
    <div class="col-md-8 col-lg-6">
        <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g. Grandma's Apple Pie" />
                <ValidationMessage For="() => _model.Title" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                    <option value="">— Select a category —</option>
                    <option value="Appetizers">Appetizers</option>
                    <option value="Main Courses">Main Courses</option>
                    <option value="Desserts">Desserts</option>
                    <option value="Salads">Salads</option>
                    <option value="Soups">Soups</option>
                </InputSelect>
                <ValidationMessage For="() => _model.Category" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients" placeholder="One ingredient per line" />
                <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Instructions</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_model.Steps" placeholder="Step-by-step instructions" />
                <ValidationMessage For="() => _model.Steps" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Recipe</button>
        </EditForm>
    </div>
</div>

@code {
    private RecipeFormModel _model = new();

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = _model.Title,
            Category = _model.Category,
            Ingredients = _model.Ingredients,
            Steps = _model.Steps
        };

        RecipeService.AddRecipe(recipe);
        Navigation.NavigateTo($"/recipe/{recipe.Id}");
    }

    private sealed class RecipeFormModel
    {
        [Required(ErrorMessage = "Please enter a recipe title.")]
        [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
        public string Title { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}

