            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                    <option value="">— Select a category —</option>
                    <option value="Appetizers">Appetizers</option>
                    <option value="Main Courses">Main Courses</option>
                    <option value="Desserts">Desserts</option>
                    <option value="Salads">Salads</option>
                    <option value="Soups">Soups</option>
                </InputSelect>
                <ValidationMessage For="() => _model.Category" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients" placeholder="One ingredient per line" />
                <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Instructions</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_model.Steps" placeholder="Step-by-step instructions" />
                <ValidationMessage For="() => _model.Steps" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Recipe</button>
        </EditForm>
    </div>
</div>

@code {
    private RecipeFormModel _model = new();

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = _model.Title,
            Category = _model.Category,
            Ingredients = _model.Ingredients,
            Steps = _model.Steps
        };

        RecipeService.AddRecipe(recipe);
        Navigation.NavigateTo($"/recipe/{recipe.Id}");
    }

    private sealed class RecipeFormModel
    {
        [Required(ErrorMessage = "Please enter a recipe title.")]
        [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
        public string Title { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}
"}

