namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];
    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Bruschetta", Category = "Appetizers",
                Ingredients = "Baguette\nTomatoes\nFresh basil\nGarlic\nOlive oil\nBalsamic vinegar\nSalt and pepper",
                Steps = "1. Slice and toast the baguette.\n2. Dice tomatoes and mix with chopped basil, minced garlic, olive oil, and balsamic vinegar.\n3. Season with salt and pepper.\n4. Spoon the tomato mixture onto the toasted bread and serve immediately.",
                Ratings = [4, 5, 5, 4]
            },
            new()
            {
                Id = 2, Title = "Stuffed Mushrooms", Category = "Appetizers",
                Ingredients = "Button mushrooms\nCream cheese\nGarlic\nParmesan\nBreadcrumbs\nParsley\nOlive oil",
                Steps = "1. Remove stems from mushrooms and hollow out caps.\n2. Mix cream cheese, minced garlic, Parmesan, breadcrumbs, and parsley.\n3. Fill each mushroom cap with the mixture.\n4. Drizzle with olive oil and bake at 375°F for 20 minutes.",
                Ratings = [5, 4, 4]
            },
            new()
            {
                Id = 3, Title = "Spaghetti Carbonara", Category = "Main Courses",
                Ingredients = "Spaghetti\nPancetta\nEggs\nParmesan cheese\nBlack pepper\nSalt",
                Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Fry pancetta until crispy.\n3. Whisk eggs with grated Parmesan and black pepper.\n4. Toss hot pasta with pancetta, then quickly stir in the egg mixture off heat.\n5. Serve immediately with extra Parmesan.",
                Ratings = [5, 5, 4, 5, 5]
            },
            new()
            {
                Id = 4, Title = "Chicken Tikka Masala", Category = "Main Courses",
                Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nOnion\nGarlic\nGinger\nRice",
                Steps = "1. Marinate chicken in yogurt, garam masala, turmeric, and cumin for 1 hour.\n2. Grill or pan-fry chicken until cooked through.\n3. Sauté onion, garlic, and ginger, then add tomato sauce and cream.\n4. Add chicken to the sauce and simmer for 15 minutes.\n5. Serve over steamed rice.",
                Ratings = [5, 4, 5, 4]
            },
            new()
            {
                Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract\nPowdered sugar",
                Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until fluffy, then fold in the chocolate mixture.\n3. Add flour and vanilla extract, mix gently.\n4. Pour into greased ramekins and bake at 425°F for 12 minutes.\n5. Invert onto plates and dust with powdered sugar.",
                Ratings = [5, 5, 5, 4, 5]
            },
            new()
            {
                Id = 6, Title = "Tiramisu", Category = "Desserts",
                Ingredients = "Ladyfinger biscuits\nEspresso\nMascarpone\nEggs\nSugar\nCocoa powder\nKahlúa (optional)",
                Steps = "1. Brew espresso and let it cool; optionally add Kahlúa.\n2. Whisk egg yolks with sugar until pale, then fold in mascarpone.\n3. Whip egg whites to stiff peaks and fold into mascarpone mixture.\n4. Dip ladyfingers in espresso and layer in a dish.\n5. Spread mascarpone cream over each layer. Repeat.\n6. Refrigerate for 4 hours and dust with cocoa powder before serving.",
                Ratings = [5, 5, 4]
            },
            new()
            {
                Id = 7, Title = "Caesar Salad", Category = "Salads",
                Ingredients = "Romaine lettuce\nCroutons\nParmesan\nCaesar dressing\nLemon juice\nAnchovy paste\nGarlic",
                Steps = "1. Wash and chop romaine lettuce.\n2. Make dressing: whisk Caesar dressing base with lemon juice, anchovy paste, and minced garlic.\n3. Toss lettuce with dressing and croutons.\n4. Top with shaved Parmesan and freshly ground pepper.",
                Ratings = [4, 4, 3, 4]
            },
            new()
            {
                Id = 8, Title = "Greek Salad", Category = "Salads",
                Ingredients = "Cucumber\nTomatoes\nRed onion\nKalamata olives\nFeta cheese\nOlive oil\nOregano\nLemon juice",
                Steps = "1. Chop cucumber, tomatoes, and red onion into chunks.\n2. Add Kalamata olives and crumbled feta.\n3. Drizzle with olive oil and lemon juice.\n4. Sprinkle with dried oregano and toss gently.",
                Ratings = [4, 5, 4]
            },
            new()
            {
                Id = 9, Title = "Tomato Basil Soup", Category = "Soups",
                Ingredients = "Canned tomatoes\nOnion\nGarlic\nFresh basil\nVegetable broth\nHeavy cream\nOlive oil\nSalt and pepper",
                Steps = "1. Sauté diced onion and garlic in olive oil until soft.\n2. Add canned tomatoes and vegetable broth; bring to a boil.\n3. Simmer for 20 minutes, then blend until smooth.\n4. Stir in heavy cream and chopped basil.\n5. Season with salt and pepper.",
                Ratings = [4, 5, 5, 4, 5]
            },
            new()
            {
                Id = 10, Title = "French Onion Soup", Category = "Soups",
                Ingredients = "Yellow onions\nButter\nBeef broth\nDry white wine\nThyme\nBay leaf\nFrench bread\nGruyère cheese",
                Steps = "1. Slice onions thinly and cook in butter over low heat for 40 minutes until caramelized.\n2. Add wine and cook until reduced.\n3. Add beef broth, thyme, and bay leaf; simmer 20 minutes.\n4. Ladle into oven-safe bowls, top with bread and Gruyère.\n5. Broil until cheese is bubbly and golden.",
                Ratings = [5, 5, 4, 5]
            }
        ];
        _nextId = 11;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }
}

