toolArgs.new_str:
﻿@page "/"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>RecipeShare — Home</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">Welcome to RecipeShare</h1>
    <p class="lead text-muted">Discover and share delicious recipes from our community.</p>
    <a href="/submit" class="btn btn-primary btn-lg">Submit Your Recipe</a>
</div>

<h2 class="mb-4">Browse by Category</h2>

<div class="row">
    @foreach (var category in _categories)
    {
        <div class="col-md-6 col-lg-4 mb-4">
            <div class="card h-100 category-card">
                <div class="card-body text-center">
                    <h3 class="card-title">
                        <span class="category-icon">@GetCategoryIcon(category)</span>
                        @category
                    </h3>
                    <p class="card-text text-muted">
                        @RecipeService.GetByCategory(category).Count recipe@(RecipeService.GetByCategory(category).Count != 1 ? "s" : "")
                    </p>
                    <a href="/category/@category" class="btn btn-outline-primary">Browse @category</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private List<string> _categories = [];

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private static string GetCategoryIcon(string category) => category switch
    {
        "Appetizers" => "🥗",
        "Main Courses" => "🍽️",
        "Desserts" => "🍰",
        "Salads" => "🥬",
        "Soups" => "🍲",
        _ => "📖"
    };
}

