.star-rating {
    display: flex;
    align-items: center;
    gap: 2px;
    margin: 0.5rem 0;
}

.star-rating .star {
    font-size: 1.8rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s, transform 0.15s;
    user-select: none;
    line-height: 1;
}

.star-rating .star:hover,
.star-rating .star.filled {
    color: #f5a623;
}

.star-rating .star:hover {
    transform: scale(1.2);
}

.rating-info {
    margin-left: 0.75rem;
    font-size: 0.9rem;
    color: #666;
}

.rating-thanks {
    color: #28a745;
    font-weight: 500;
    margin-right: 0.5rem;
}

